"""Simple waitqueue source lessons. Pending runtime model and integration."""
ROWS = [
('Swait 설계·제한된 기능으로 잠금 구간 줄이기', 'include/linux/swait.h', 'swait_queue_head',
 'simple waitqueue는 일반 waitqueue의 모든 기능을 제공하지 않습니다. 사용자 깨움 콜백과 비 exclusive 모드를 없애고, 같은 대기열에서 서로 다른 수면 유형을 섞는 사용을 제한합니다. 모든 깨움은 TASK_NORMAL을 대상으로 하며 swake_up_one은 첫 항목 하나를 처리합니다. raw spinlock을 사용할 수 있도록 임의 콜백의 실행 시간을 제거한 설계입니다. 헤더는 특별한 실시간 제약이 있는 경우에만 사용하고 보통은 일반 waitqueue를 권합니다.',
 '사용자 콜백, poll 이벤트, 서로 다른 대기 state 필터가 필요하면 일반 waitqueue를 검토하세요. 모든 기능을 가진 빠른 대기열이라고 생각하지 마세요. 필요한 기능을 줄여 잠금·IRQ 보유 구간을 제한한다는 원리를 확인합니다.',
 [('swait가 임의 사용자 깨움 콜백을 지원하나요?', '아닙니다. 제한된 task 깨움 구조입니다.', '맞습니다. 일반 waitqueue의 func를 그대로 가집니다.', '헤더는 실행 시간 보장을 어렵게 만드는 사용자 콜백을 제거한 설계를 명시합니다. raw spinlock과 기능 제한을 연결해서 이해하세요.'),
  ('일반적인 대기에도 무조건 swait를 선택하라고 원문이 권하나요?', '아닙니다. 특별한 실시간 제약에서 사용하도록 설명합니다.', '맞습니다. 모든 waitqueue의 교체용입니다.', '원문은 대부분의 경우 일반 waitqueue를 유지하는 편이 좋다고 설명합니다. 성능 이름보다 필요한 기능과 문맥을 먼저 확인하세요.')]),
('Swait 자료구조·task와 raw spinlock', 'include/linux/swait.h', 'swait_queue',
 'swait_queue는 task 포인터와 리스트 링크만 가집니다. 일반 wait_queue_entry의 flags, private와 func가 없습니다. head는 raw_spinlock_t와 task_list 센티널입니다. 작은 항목 표현과 고정 깨움 동작이 임의 콜백을 실행하지 않는 설계에 맞물립니다. 자료형이 다르므로 일반 waitqueue 항목과 head를 서로 바꿔 전달할 수 없습니다.',
 '구조체의 두 멤버를 현재 task 등록과 리스트 연결로 구별하세요. 별도 콜백이나 이벤트 key를 추가하려고 일반 waitqueue API에 캐스팅하지 마세요. 객체 수명은 연결된 항목과 깨움이 더 이상 접근하지 않을 때까지 유지합니다.',
 [('swait_queue의 대기 대상 멤버는 무엇인가요?', 'struct task_struct 포인터입니다.', '임의 콜백 함수 포인터입니다.', '원문 항목은 task와 task_list로 구성됩니다. 일반 waitqueue의 사용자 private·func 구조와 다릅니다.'),
  ('swait_queue_head의 잠금 타입은 무엇인가요?', 'raw_spinlock_t입니다.', '항상 mutex입니다.', '원문 head는 raw spinlock과 리스트를 가집니다. task가 실제 잠드는 구간에는 해당 잠금을 풀어야 합니다.')]),
('Swait 초기화·정적 선언과 실행 중 head 설정', 'kernel/sched/swait.c', '__init_swait_queue_head',
 'head 초기화 함수는 raw spinlock을 초기화하고 lockdep 클래스와 이름을 연결한 뒤 task_list를 자기 참조로 만듭니다. 헤더의 정적 head 선언도 잠금과 빈 리스트를 구성합니다. DECLARE_SWAITQUEUE는 current와 자기 참조 항목 링크를 설정합니다. CONFIG_LOCKDEP의 스택 head 선언은 실행 중 초기화를 사용하여 잠금 분류를 준비합니다.',
 '새 head는 사용 전에 초기화하고, 사용 중인 리스트를 재초기화하지 마세요. 스택 대기 항목의 수명과 대기 등록 기간을 맞춥니다. 현재 task를 설정하는 정적 지역 항목 선언과 head 선언을 구별합니다.',
 [('DECLARE_SWAITQUEUE는 task 멤버를 무엇으로 초기화하나요?', 'current로 초기화합니다.', '항상 NULL로 초기화합니다.', '헤더의 지정 초기화는 current와 LIST_HEAD_INIT를 함께 사용합니다. head 초기화와 개별 대기 항목 초기화를 구분하세요.'),
  ('head의 실행 중 초기화는 리스트 연결도 준비하나요?', '그렇습니다. task_list를 자기 참조로 만듭니다.', '아닙니다. 잠금만 준비합니다.', '함수는 raw_spin_lock_init, lockdep 설정, INIT_LIST_HEAD를 수행합니다. 등록 전에 head 전체의 초기 상태가 필요합니다.')]),
('Swait active·조건 공개와 배리어', 'include/linux/swait.h', 'swait_active',
 'swait_active는 task_list가 비었는지 잠금 없이 조회합니다. 원문은 일반 waitqueue_active와 같은 놓친 깨움 위험을 명시합니다. 조건을 바꾼 waker가 이 조회로 깨움을 생략하려면 잠금 또는 명시적 smp_mb 규약을 지켜야 합니다. swq_has_sleeper는 smp_mb 뒤 active를 호출합니다. 기능이 단순해져도 task 등록과 조건 관측의 메모리 순서 문제까지 사라지는 것은 아닙니다.',
 '조건 저장, 배리어, 리스트 관측과 waiter의 준비·조건 재검사 순서를 함께 표시하세요. active가 true라는 사실만으로 task가 지금 잠들어 있거나 객체 수명을 소유한다고 가정하지 않습니다.',
 [('swait_active 자체가 raw spinlock을 잡나요?', '아닙니다. 리스트 존재 여부만 조회합니다.', '맞습니다. 모든 조회는 잠금 포함입니다.', '함수 본문은 !list_empty입니다. 호출자 프로토콜의 잠금이나 배리어 조건을 별도로 지켜야 합니다.'),
  ('simple waitqueue이면 메모리 배리어를 모두 제거해도 되나요?', '아닙니다. 조건과 등록 관측의 순서가 필요합니다.', '맞습니다. 항목에 콜백이 없어서 순서 문제도 없습니다.', '원문은 일반 대기열과 같은 놓친 깨움 위험을 설명합니다. 기능 제한과 메모리 순서 보장은 서로 다른 문제입니다.')]),
('Swait locked wake·첫 항목 제거와 깨움 결과', 'kernel/sched/swait.c', 'swake_up_locked',
 'swake_up_locked는 비어 있으면 끝내고, 첫 항목의 task에 TASK_NORMAL과 지정 wake_flags로 try_to_wake_up을 호출합니다. 그 반환값을 검사하지 않고 list_del_init으로 항목을 제거합니다. 이미 실행 중이라 깨움 결과가 0이어도 항목 제거는 진행됩니다. 일반 autoremove 콜백의 성공 때만 제거하는 계약과 다릅니다. 호출자는 raw head 잠금을 보유한 문맥을 지켜야 합니다.',
 '깨움 결과와 등록 제거를 구별하세요. 다시 기다려야 하면 조건 반복문이 항목을 재등록합니다. 내부 locked 함수를 head 잠금 없이 호출하거나 별도 task 상태 필터를 기대하지 마세요.',
 [('try_to_wake_up이 0이어도 항목을 제거하나요?', '그렇습니다. 반환값에 조건을 두지 않습니다.', '아닙니다. 성공일 때만 제거합니다.', '원문은 깨움 호출 다음에 무조건 list_del_init을 수행합니다. 일반 autoremove의 if(ret) 삭제와 다른 계약입니다.'),
  ('locked wake는 어떤 항목을 처리하나요?', '리스트 첫 항목 하나입니다.', '모든 상태를 필터링해 마지막 항목을 찾습니다.', '본문은 list_first_entry를 읽습니다. 사용자 state 필터를 찾아 O(n) 순회하는 일반 깨움 구조가 아닙니다.')]),
('Swait wake one·IRQ 상태 보존과 한 항목', 'kernel/sched/swait.c', 'swake_up_one',
 'swake_up_one은 raw_spin_lock_irqsave로 head를 보호하고 locked wake를 한 번 호출한 뒤 이전 IRQ 상태를 복구합니다. 항목이 없으면 잠금 구간 안에서 아무 task도 처리하지 않습니다. 한 항목의 처리는 여러 task 중 조건을 실제 소비한 task가 정확히 한 명임을 증명하지는 않습니다. 호출자는 조건 변경과 task가 다시 검사하는 프로토콜을 함께 유지합니다.',
 '일부 대기자만 처리하는 사건에서 단일 항목 깨움과 실제 공유 자원 소비를 구분합니다. IRQ가 원래 꺼진 문맥에서도 save·restore 규약을 확인하세요. 반환 결과로 작업 완료를 판단하지 않습니다.',
 [('swake_up_one은 이전 IRQ 상태를 저장·복원하나요?', '그렇습니다. irqsave와 irqrestore를 사용합니다.', '아닙니다. 언제나 IRQ를 켜고 끝냅니다.', '본문은 flags에 이전 상태를 저장하는 raw 잠금 쌍입니다. all 변형의 irq 계약과 구별해야 합니다.'),
  ('한 항목을 깨우면 그 task의 작업 완료도 보장되나요?', '아닙니다. 조건을 다시 검사하고 처리해야 합니다.', '맞습니다. wake 함수가 처리 완료까지 기다립니다.', '깨움은 실행 가능 상태로의 전환을 시도합니다. 공유 조건 소비나 작업 완료는 깨어난 task의 후속 동작입니다.')]),
('Swait wake all·snapshot 리스트와 반복 잠금 해제', 'kernel/sched/swait.c', 'swake_up_all',
 'swake_up_all은 IRQ를 끄고 raw 잠금을 잡아 기존 task_list를 임시 리스트로 옮깁니다. 각 task를 깨우고 항목을 제거하며, 남은 항목이 있으면 잠금과 IRQ를 풀었다가 다시 잡습니다. 따라서 여러 항목을 처리하는 동안 상위 우선순위 task가 실행할 기회를 얻습니다. 임시 리스트를 만든 뒤 head에 새로 등록된 task는 이번 임시 리스트의 대상에 자동 포함되지 않습니다. 원문은 IRQ가 이미 꺼진 문맥에서 이 함수를 사용하지 못한다고 명시합니다.',
 'IRQ가 활성인 사용 문맥과 등록 시점 snapshot을 확인하세요. all이라는 이름을 호출 중 모든 새 등록까지 끝없이 처리하는 보장으로 해석하지 마세요. 각 잠금 구간을 제한하려는 목적과 함수 전체의 O(n) 작업량을 구별합니다.',
 [('호출 시작 뒤 head에 새로 등록된 항목도 반드시 임시 리스트에 들어가나요?', '아닙니다. 처음 옮긴 리스트의 snapshot을 처리합니다.', '맞습니다. 모든 새 항목을 계속 흡수합니다.', 'list_splice_init은 당시 head의 리스트를 tmp로 옮깁니다. 이후 head 등록은 별도 리스트에 있으므로 이번 반복 대상과 구별됩니다.'),
  ('IRQ가 이미 꺼진 상태에서도 swake_up_all을 일반적으로 호출하나요?', '아닙니다. 원문은 그 사용을 금지합니다.', '맞습니다. irqsave 변형과 완전히 같습니다.', '이 함수는 항목 사이에 IRQ를 풀어 보유 시간을 제한해야 합니다. one의 저장·복원 방식과 동일하지 않습니다.')]),
('Swait all locked·completion 전용 예외', 'kernel/sched/swait.c', 'swake_up_all_locked',
 'all locked 함수는 리스트가 빌 때까지 locked wake를 반복하며 항목 사이에 잠금을 풀지 않습니다. 원문은 이 인터페이스가 completion을 위해서만 노출되며 일반 사용용이 아니라고 명시합니다. swake_up_all과 달리 hard IRQ와 IRQ 비활성 문맥을 허용하려는 별도 설계입니다. 따라서 모든 all 함수가 반복마다 잠금을 풀어 보유 시간을 제한한다고 일반화하면 안 됩니다.',
 'completion의 상위 잠금과 호출 계약에서 사용법을 확인하세요. 일반 swait 사용자에게 IRQ-off 우회 함수로 임의 권하지 않습니다. 기능 범위와 예외 문맥을 원문 주석에 맞춰 구별합니다.',
 [('all locked도 항목 사이마다 head 잠금을 풀나요?', '아닙니다. 잠금 보유 상태의 반복입니다.', '맞습니다. 일반 all과 완전히 같습니다.', '본문은 swake_up_locked를 반복하며 unlock 호출이 없습니다. 두 all 인터페이스의 보유 시간과 문맥 계약은 다릅니다.'),
  ('원문은 all locked를 무엇을 위한 인터페이스로 설명하나요?', 'completion을 위한 인터페이스입니다.', '모든 일반 swait의 권장 기본 함수입니다.', '주석은 completion에만 노출되고 일반 사용용이 아니라고 명시합니다. 특별한 예외를 보편적인 API 계약으로 확대하지 마세요.')]),
('Swait prepare·current와 tail 등록', 'kernel/sched/swait.c', '__prepare_to_swait',
 '내부 준비 함수는 wait의 task를 current로 설정하고 항목이 아직 연결되지 않았으면 tail에 등록합니다. 외부 prepare_to_swait_exclusive는 raw 잠금과 IRQ 저장 구간에서 이 함수를 호출하고 대기 상태를 설정한 뒤 이전 IRQ 상태를 복구합니다. 이미 연결된 항목은 다시 추가하지 않습니다. 내부 함수는 스스로 head 잠금을 잡지 않으므로 외부 보호 문맥과 함께 읽어야 합니다.',
 '항목 링크를 자기 참조로 초기화한 뒤 prepare, 조건 검사, 필요할 때 schedule, 종료 후 finish의 순서를 지킵니다. 등록 반복이 중복 삽입이 되지 않도록 연결 상태를 보존하고 내부 helper의 잠금 책임을 확인합니다.',
 [('새 항목은 어디에 등록되나요?', 'task_list의 맨 뒤입니다.', '항상 현재 첫 항목을 덮어씁니다.', '내부 함수는 list_add_tail을 사용합니다. current 설정과 링크 등록은 서로 다른 멤버의 동작입니다.'),
  ('__prepare_to_swait가 head 잠금을 직접 잡나요?', '아닙니다. 외부 보호 문맥이 필요합니다.', '맞습니다. 내부 helper만 호출해도 모든 보호가 됩니다.', '내부 본문은 task 설정과 리스트 등록입니다. 외부 prepare 함수가 raw 잠금과 IRQ 저장으로 보호합니다.')]),
('Swait signal 준비·항목 제거와 조건 우선', 'kernel/sched/swait.c', 'prepare_to_swait_event',
 'signal 준비는 raw 잠금 아래 state에 허용된 signal을 검사합니다. 있으면 항목을 list_del_init으로 제거하고 -ERESTARTSYS를 반환합니다. 없으면 current를 등록하고 대기 상태를 설정합니다. 공통 swait 매크로는 이 반환 뒤 조건을 먼저 검사하여 이미 충족된 조건을 성공으로 처리할 수 있습니다. signal 실패가 다음 swake_up_one의 대상에 남지 않도록 제거하는 규약입니다.',
 'signal 중단과 조건 성공을 같은 반환값으로 다루지 마세요. 조건이 false일 때 오류 경로가 적용되는 순서를 직접 추적합니다. 직접 호출하는 코드에서는 task 상태와 항목 수명의 정리 계약도 확인합니다.',
 [('허용된 signal 경로가 반환하는 값은 무엇인가요?', '-ERESTARTSYS입니다.', '항상 -EINTR입니다.', '원문은 일반 waitqueue와 같은 재시작 오류를 사용합니다. rcuwait의 오류 계약과 섞지 마세요.'),
  ('signal 경로에서 항목은 다음 one 깨움의 대상에 남나요?', '아닙니다. 리스트에서 제거합니다.', '맞습니다. 다른 waiter보다 먼저 선택됩니다.', '주석은 후속 swake_up_one이 실패할 waiter를 보지 않아야 한다고 설명합니다. 등록 제거와 오류 반환을 함께 수행합니다.')]),
('Swait finish·내부 제거와 careful 조회', 'kernel/sched/swait.c', 'finish_swait',
 'finish_swait는 TASK_RUNNING을 복구하고 list_empty_careful로 항목을 조회합니다. 남아 있으면 raw 잠금과 IRQ 저장 구간에서 제거하고 자기 참조를 복구합니다. 내부 __finish_swait는 상태를 복구한 뒤 일반 list_empty 검사와 삭제를 수행하지만 잠금을 자체 획득하지 않습니다. 내부 helper를 같은 이름의 잠금 포함 API처럼 사용해서는 안 됩니다.',
 '직접 대기 반복문을 끝낼 때 잠금 포함 finish로 항목과 상태를 정리하세요. 내부 helper를 사용하려면 상위 보호 문맥을 확인합니다. 스택 대기 항목이 함수 반환 뒤에도 리스트에 남지 않도록 합니다.',
 [('finish_swait의 조건부 삭제는 raw 잠금 아래 수행되나요?', '그렇습니다.', '아닙니다. 전체 삭제가 잠금 없이 진행됩니다.', '잠금 밖에서는 careful 조회를 하고, 실제 삭제는 irqsave 잠금 구간에서 합니다. 조회와 변경의 보호 문맥을 구분하세요.'),
  ('__finish_swait도 직접 잠금을 획득하나요?', '아닙니다. 내부 helper입니다.', '맞습니다. 밑줄 함수가 항상 잠금 포함입니다.', '내부 본문에는 raw 잠금 호출이 없습니다. 상위 호출 문맥의 책임을 함수 이름만으로 판단하지 마세요.')]),
('Swait 공통 macro·스택 항목과 오류 label', 'include/linux/swait.h', '___swait_event',
 '공통 매크로는 스택 swait_queue의 링크를 초기화하고 반복마다 prepare_to_swait_event를 호출합니다. 조건 성공이면 finish_swait를 거쳐 끝납니다. 조건이 false이며 중단 가능한 state에서 준비 오류가 있으면 __out label로 이동하여 오류를 반환합니다. 이 오류 경로는 finish를 건너뛰며 준비 함수가 이미 항목을 제거하는 계약과 연결됩니다. 모든 swait 등록이 exclusive라는 점도 일반 공통 매크로와의 차이입니다.',
 'GNU statement expression, 지역 label과 long __ret의 역할을 확인하세요. 조건식은 반복 평가에 안전하게 만듭니다. 성공 경로와 오류 경로의 정리를 각각 따라가며 rcuwait와 같은 종료 구조라고 가정하지 않습니다.',
 [('준비 오류의 signal 경로도 반드시 finish_swait를 호출하나요?', '아닙니다. __out으로 이동합니다.', '맞습니다. 모든 경로에서 finish를 호출합니다.', 'goto label은 finish 뒤에 있습니다. 준비 함수의 항목 제거와 함께 읽어야 정리 절차를 올바르게 이해할 수 있습니다.'),
  ('swait 공통 매크로는 비 exclusive 항목을 선택할 인자가 있나요?', '아닙니다. 모두 exclusive인 설계입니다.', '맞습니다. 매크로가 자동으로 일반 콜백을 등록합니다.', 'simple 대기열은 비 exclusive 기능을 제거했습니다. 공통 매크로에도 일반 waitqueue의 exclusive 선택 인자가 없습니다.')]),
('Swait wrapper·일반·interruptible·idle 선택', 'include/linux/swait.h', 'swait_event_exclusive',
 '일반 exclusive wrapper는 TASK_UNINTERRUPTIBLE과 schedule을 선택하며 do-while 문으로 사용합니다. interruptible wrapper는 TASK_INTERRUPTIBLE에 성공 0과 signal 오류 반환을 결합합니다. idle wrapper는 TASK_IDLE을 선택하여 system load에 기여하지 않는 대기를 표현하며 원문은 signal을 무시한다고 설명합니다. 바깥 조건이 true이면 내부 등록과 실제 대기를 생략합니다.',
 '필요한 대기 state와 반환 사용 문법에 맞는 wrapper를 선택하세요. 같은 swait head에서 수면 유형을 섞지 않는 헤더의 제한을 확인합니다. idle을 CPU busy loop나 모든 signal 중단 가능으로 해석하지 않습니다.',
 [('swait idle wrapper는 어떤 state를 사용하나요?', 'TASK_IDLE입니다.', '항상 TASK_INTERRUPTIBLE입니다.', '원문 wrapper와 설명은 load에 기여하지 않는 TASK_IDLE 대기를 명시합니다. signal 계약도 해당 상태에 맞춰 읽어야 합니다.'),
  ('초기 조건이 true이면 내부 등록을 생략할 수 있나요?', '그렇습니다.', '아닙니다. 모든 wrapper가 반드시 잠듭니다.', '바깥 조건 검사에서 내부 대기 매크로를 실행하지 않을 수 있습니다. 대기 함수 호출과 실제 수면은 구별해야 합니다.')]),
('Swait timeout·jiffies와 경계 성공 1', 'include/linux/swait.h', 'swait_event_timeout_exclusive',
 'timeout wrapper는 일반 waitqueue의 ___wait_cond_timeout helper를 재사용합니다. 조건 미충족 만료는 0, 만료 경계의 조건 성공은 1, 일찍 성공하면 최소 1인 남은 jiffies를 반환합니다. 일반·interruptible·idle timeout은 state 선택이 다르며 interruptible은 -ERESTARTSYS를 반환할 수도 있습니다. 내부 명령은 schedule_timeout으로 __ret의 남은 시간을 갱신합니다.',
 '양수 성공, 0 만료와 음수 오류를 나누어 처리하세요. 시간 단위를 jiffies로 확인합니다. 값 1만으로 정확한 수면 기간을 계산하지 마세요. 조건과 signal을 함께 관측했을 때의 조건 우선 규칙도 유지됩니다.',
 [('timeout 0에서 조건이 true이면 반환값은 무엇인가요?', '성공을 구별하는 1입니다.', '항상 시간 만료의 0입니다.', '재사용하는 timeout helper는 조건이 true이고 __ret가 0이면 1로 조정합니다. 일반 waitqueue와 같은 경계 계약입니다.'),
  ('interruptible timeout에서 ret가 음수이면 조건 성공인가요?', '아닙니다. signal 오류입니다.', '맞습니다. 0이 아니면 모두 성공입니다.', '양수 잔여 시간과 음수 오류를 구분해야 합니다. C의 if(ret)는 두 영역을 모두 참으로 처리합니다.')])
]

def register(topic, q, detail):
    for title, path, symbol, principle, use, qa in ROWS:
        topic(title, '동기화', path, symbol,
              '실제 simple waitqueue의 기능 제한, raw 잠금과 task 등록·깨움·정리 순서를 통해 실시간 대기 기술의 사용 조건을 배웁니다.',
              principle, use,
              '일반 waitqueue와 비교하며 등록 위치, 잠금·IRQ 구간과 조건·반환값을 별도로 추적하세요.',
              *(q(*x) for x in qa), details=[
                  detail('원문 확인', '고정 Linux v6.12의 swait.h와 kernel/sched/swait.c 전체를 읽고 해당 정의와 주석을 대조했습니다.'),
                  detail('검증 범위', '전체 원문을 명시적 리스트·raw 잠금·IRQ·task·스케줄러 직렬 모델에 연결하여 선택한 사례 56,002건을 최적화 및 ASan·UBSan 구성에서 각각 검사했습니다. 전체 깨움 사이의 새 등록도 결정적 교차 실행으로 확인했습니다. 실제 RT 보유 시간·커널 선점·SMP·메모리 순서의 증명은 아닙니다.')])
